export const getMockData = async (endpoint, options = {}) => {
  const method = options.method || 'GET';
  
  // Simulate network delay
  await new Promise(resolve => setTimeout(resolve, 500));

  if (endpoint.includes('/login')) {
    return {
      token: "mock-token-123",
      user: { id: 1, name: "Demo User", email: "demo@example.com", role: "candidate" },
      message: "Login successful"
    };
  }
  
  if (endpoint.includes('/register')) {
    return {
      token: "mock-token-123",
      user: { id: 1, name: JSON.parse(options.body).name, email: JSON.parse(options.body).email, role: JSON.parse(options.body).role },
      message: "Registration successful"
    };
  }

  if (endpoint.includes('/profile/')) {
    return {
      id: 1,
      name: "Demo User",
      email: "demo@example.com",
      title: "Software Engineer",
      skills: ["React", "Node.js", "Python"],
      about: "A passionate developer looking for opportunities.",
      avatar: null,
      role: "candidate",
      cv_url: null,
    };
  }

  if (endpoint.includes('/jobs') && method === 'GET') {
    return [
      { id: 1, title: "Frontend Developer", company: "Tech Corp", location: "Remote", type: "Full-time", salary: "$80k - $100k", description: "Looking for a React expert." },
      { id: 2, title: "Backend Engineer", company: "Data Inc", location: "New York", type: "Contract", salary: "$100k - $120k", description: "Node.js and Database architecture." },
      { id: 3, title: "UI/UX Designer", company: "Creative Studio", location: "London", type: "Part-time", salary: "£40k", description: "Design beautiful interfaces." },
    ];
  }

  if (endpoint.includes('/candidates/suggested')) {
    return [
      { id: 101, name: "Alice Smith", title: "React Developer", skills: ["React", "TypeScript", "Tailwind"], matchScore: 95 },
      { id: 102, name: "Bob Johnson", title: "Fullstack Engineer", skills: ["Node.js", "React", "MongoDB"], matchScore: 88 },
      { id: 103, name: "Charlie Davis", title: "Frontend Intern", skills: ["HTML", "CSS", "JS"], matchScore: 70 },
    ];
  }

  if (endpoint.includes('/cv/upload')) {
    return { message: "CV Uploaded Successfully (Mock)", cvUrl: "/mock-cv.pdf" };
  }

  if (endpoint.includes('/interview/start')) {
    return { sessionId: "mock-session-123", message: "Interview started" };
  }

  if (endpoint.includes('/interview/')) {
    if (method === 'POST') {
      return { message: "Answer submitted successfully", feedback: "Good answer, try to elaborate more on your problem-solving process." };
    }
  }

  if (endpoint.includes('/notifications')) {
    return [
      { id: 1, message: "Your application was viewed by Tech Corp.", read: false, created_at: new Date().toISOString() },
      { id: 2, message: "New job matches your profile.", read: true, created_at: new Date(Date.now() - 86400000).toISOString() }
    ];
  }

  if (endpoint.includes('/ratings')) {
    return [
      { id: 1, user_name: "Sarah M.", rating: 5, comment: "This platform really helped me land a job!", created_at: new Date().toISOString() },
      { id: 2, user_name: "Ahmed K.", rating: 4, comment: "Great AI interview practice tool.", created_at: new Date().toISOString() }
    ];
  }

  // Default fallback mock response
  return { success: true, message: "Mock response for " + endpoint, data: [] };
};
